Rule.Source:
import java.text.Normalizer;
import sailpoint.object.Filter;
import sailpoint.object.Identity;
import sailpoint.object.QueryOptions;
import sailpoint.tools.Util;

// Unbound arguments are void, not null, in BeanShell.
if (account == void || account == null || identity == void || identity == null) {
    return;
}

String toKey(Object value) {
    if (value == null) return "";
    String s = Normalizer.normalize(value.toString(), Normalizer.Form.NFD);
    return s.toLowerCase().replaceAll("[^a-z0-9]", "");
}

String first = toKey(account.getAttribute("firstName"));
String last  = toKey(account.getAttribute("lastName"));
String empNo = toKey(account.getAttribute("employeeNumber"));

String base;
if (Util.isNotNullOrEmpty(first) && Util.isNotNullOrEmpty(last)) {
    base = first + "." + last;
} else if (Util.isNotNullOrEmpty(last)) {
    base = last;
} else {
    base = empNo;
}
if (Util.isNullOrEmpty(base)) {
    // Nothing usable in the row; leave IIQ's default name alone.
    return;
}

String candidate = base;
QueryOptions qo = new QueryOptions();
qo.addFilter(Filter.eq("name", candidate));
if (context.countObjects(Identity.class, qo) > 0 && Util.isNotNullOrEmpty(empNo)) {
    candidate = base + "." + empNo;
}

identity.setName(candidate);
